export interface Vec2 {
  x: number;
  y: number;
}

export interface CircleAabbResult {
  /** True if the circle and AABB overlap (penetration > 0). */
  hit: boolean;
  /** Overlap depth along the collision normal (0 when not hitting). */
  penetration: number;
  /** Unit normal pointing from the closest box surface toward the circle center. */
  normal: Vec2;
}

/**
 * Circle vs axis-aligned bounding box collision.
 *
 * Clamps the circle center to the box to find the closest point on the box,
 * then measures the distance from that point to the center.
 */
export function circleAabb(
  cx: number,
  cy: number,
  radius: number,
  boxX: number,
  boxY: number,
  boxW: number,
  boxH: number
): CircleAabbResult {
  // Closest point on the box to the circle center.
  const px = Math.min(Math.max(cx, boxX), boxX + boxW);
  const py = Math.min(Math.max(cy, boxY), boxY + boxH);

  let dx = cx - px;
  let dy = cy - py;
  const distSq = dx * dx + dy * dy;

  // Center inside the box (or exactly on its boundary): push out through
  // the nearest face.
  if (distSq < Number.EPSILON) {
    const left = cx - boxX;
    const right = boxX + boxW - cx;
    const top = cy - boxY;
    const bottom = boxY + boxH - cy;

    const min = Math.min(left, right, top, bottom);
    let penetration: number;
    let nx = 0;
    let ny = 0;

    if (min === left) {
      penetration = radius + left; // circle fully inside: must cross the face plus radius
      nx = -1;
    } else if (min === right) {
      penetration = radius + right;
      nx = 1;
    } else if (min === top) {
      penetration = radius + top;
      ny = -1;
    } else {
      penetration = radius + bottom;
      ny = 1;
    }
    return { hit: true, penetration, normal: { x: nx, y: ny } };
  }

  const dist = Math.sqrt(distSq);
  if (dist >= radius) {
    return { hit: false, penetration: 0, normal: { x: 0, y: 0 } };
  }

  const inv = 1 / dist;
  return {
    hit: true,
    penetration: radius - dist,
    normal: { x: dx * inv, y: dy * inv },
  };
}

