import { describe, expect, it } from "vitest";
import { circleAabb } from "./circleAabb";

const EPS = 1e-9;

describe("circleAabb", () => {
  it("circle beyond a corner penetrates along the normalized diagonal", () => {
    // Box [0,4]x[0,4]; circle center at (6,6) is sqrt(8) from corner (4,4),
    // but sqrt(2) from closest point (5,5). Radius 2 => penetration
    // 2 - sqrt(2) along the normalized (1,1) direction.
    const res = circleAabb(6, 6, 2, 0, 0, 4, 4);

    expect(res.hit).toBe(true);
    expect(res.penetration).toBeCloseTo(2 - Math.SQRT2, 9);
    expect(res.normal.x).toBeCloseTo(Math.SQRT1_2, 9); // 1/sqrt(2)
    expect(res.normal.y).toBeCloseTo(Math.SQRT1_2, 9);
    expect(res.normal.x * res.normal.x + res.normal.y * res.normal.y).toBeCloseTo(1, EPS);
  });

  it("circle centered inside the box picks the nearest face normal", () => {
    // Box [0,10]x[0,10]; center at (3, 5) is 3 from the left face,
    // 7 from right/top/bottom -> nearest face is left (-1, 0).
    const res = circleAabb(3, 5, 1, 0, 0, 10, 10);

    expect(res.hit).toBe(true);
    expect(res.penetration).toBeCloseTo(1 + 3, EPS); // radius + distance to nearest face
    expect(res.normal.x).toBeCloseTo(-1, EPS);
    expect(res.normal.y).toBeCloseTo(0, EPS);

    // Same box, center at (5, 8): nearest face is top (0, -1).
    const res2 = circleAabb(5, 8, 0.5, 0, 0, 10, 10);
    expect(res2.hit).toBe(true);
    expect(res2.penetration).toBeCloseTo(0.5 + 2, EPS);
    expect(res2.normal.x).toBeCloseTo(0, EPS);
    expect(res2.normal.y).toBeCloseTo(-1, EPS);
  });

  it("circle exactly touching a face reports zero penetration, not a collision", () => {
    // Box [0,4]x[0,4]; circle of radius 2 centered at (6, 2) touches the
    // right face (x=4) exactly: distance from closest point == radius.
    const res = circleAabb(6, 2, 2, 0, 0, 4, 4);

    expect(res.hit).toBe(false);
    expect(res.penetration).toBe(0);
  });
});

